const now       = DateTime.now().setZone('America/New_York');
const isNight   = now.hour >= 22 || now.hour < 7;
const onTheHour = now.minute === 0;
const shouldRun = isNight || (!isNight && onTheHour);

return [{
  json: {
    shouldRun,
    periodLabel: isNight
      ? '🌙 Nighttime Mode — every 10 min'
      : '☀️ Daytime Mode — every 1 hour',
    checkedAt: now.toFormat('yyyy-MM-dd HH:mm:ss')
  }
}];

// ================================================================
// GENERATE ALL 18 DATES: July 1 to July 18, 2026
// Each date becomes a separate item — Apify node runs once per item
// ================================================================
const sd = $getWorkflowStaticData('global');
sd.periodLabel = $('Smart Schedule Gate').first().json.periodLabel;
sd.checkedAt   = $('Smart Schedule Gate').first().json.checkedAt;

const dates = [];
let cur = DateTime.fromISO('2026-07-01', { zone: 'America/New_York' });
const end = DateTime.fromISO('2026-07-18', { zone: 'America/New_York' });

while (cur <= end) {
  dates.push({
    json: {
      departureDate: cur.toFormat('yyyy-MM-dd'),
      displayDate:   cur.toFormat('EEE, MMM dd')
    }
  });
  cur = cur.plus({ days: 1 });
}

return dates;

const item = $input.item.json;

const depDate  = item?.search_parameters?.outbound_date || 'N/A';
const dispDate = depDate !== 'N/A'
  ? DateTime.fromISO(depDate, { zone: 'America/New_York' }).toFormat('EEE, MMM dd')
  : 'N/A';

const lowestPrice = item?.price_insights?.lowest_price || null;

let allFlights = [];
if (Array.isArray(item.best_flights))  allFlights = allFlights.concat(item.best_flights);
if (Array.isArray(item.other_flights)) allFlights = allFlights.concat(item.other_flights);

allFlights = allFlights
  .filter(f => f && f.price !== null && f.price !== undefined)
  .sort((a, b) => (a.price || 99999) - (b.price || 99999));

if (!allFlights.length || lowestPrice === null) {
  return [{ json: {
    departureDate: depDate,
    displayDate:   dispDate,
    available:     false,
    price:         null,
    airline:       null,
    flightNumbers: null,
    depTime:       null,
    arrTime:       null,
    duration:      null,
    stopsLabel:    null,
    layovers:      null,
    bookingLink:   null
  }}];
}

const top   = allFlights[0];
const legs  = top.flights || [];
const first = legs[0] || {};
const last  = legs[legs.length - 1] || {};
const stops = legs.length > 0 ? legs.length - 1 : 0;
const mins  = top.total_duration || 0;

const layovers = (top.layovers || []).map(l => {
  const h = Math.floor((l.duration || 0) / 60);
  const m = (l.duration || 0) % 60;
  return `${l.name || '?'} (${h}h ${m}m)`;
}).join(', ');

const flightNumbers = legs.map(l => l.flight_number || '').filter(Boolean).join(' → ') || 'N/A';
const airline  = first.airline || top.airline || 'Unknown';
const depTime  = (first.departure_airport || {}).time || 'N/A';
const arrTime  = (last.arrival_airport || {}).time || 'N/A';
const duration = mins > 0 ? `${Math.floor(mins / 60)}h ${mins % 60}m` : 'N/A';
const bookingLink = top.booking_link || top.bookingLink ||
  `https://www.google.com/travel/flights/search?q=flights+from+PHL+to+DAC+on+${depDate}&curr=USD&gl=us&hl=en`;

return [{ json: {
  departureDate: depDate,
  displayDate:   dispDate,
  available:     true,
  price:         lowestPrice,
  airline,
  flightNumbers,
  depTime,
  arrTime,
  duration,
  stopsLabel:    stops === 0 ? 'Nonstop ✈️' : `${stops} Stop${stops > 1 ? 's' : ''}`,
  layovers,
  bookingLink
}}];

// ================================================================
// MASTER AGGREGATOR
// Receives all 18 date results, finds cheapest,
// builds calendar, computes trend, decides Slack channel
// ================================================================
const TARGET = 1400;
const sd     = $getWorkflowStaticData('global');
const now    = DateTime.now().setZone('America/New_York');

const checkedAt   = now.toFormat('yyyy-MM-dd HH:mm:ss');
const periodLabel = sd.periodLabel || (now.hour >= 22 || now.hour < 7
  ? '🌙 Nighttime Mode — every 10 min'
  : '☀️ Daytime Mode — every 1 hour');

// Aggregate node wraps all 18 items into one item with a 'data' array
const raw      = $input.first().json;
const allDates = Array.isArray(raw.data) ? raw.data : [];

const available = allDates
  .filter(d => d.available && d.price !== null)
  .sort((a, b) => a.price - b.price);

if (!available.length) {
  return [{ json: {
    hasData:     false,
    belowTarget: false,
    checkedAt,
    periodLabel,
    calendarBlock: '❌ No data returned for any date.',
    error: 'No priced flights found across Jul 1–18.'
  }}];
}

const cheapest     = available[0];
const currentPrice = cheapest.price;

// Build price calendar
const byDate = {};
for (const d of allDates) {
  if (d.available && d.price !== null) byDate[d.departureDate] = d;
}

const calLines = [];
let cur = DateTime.fromISO('2026-07-01', { zone: 'America/New_York' });
const endDt = DateTime.fromISO('2026-07-18', { zone: 'America/New_York' });
while (cur <= endDt) {
  const key   = cur.toFormat('yyyy-MM-dd');
  const disp  = cur.toFormat('EEE, MMM dd');
  const entry = byDate[key];
  if (entry) {
    const isBest = key === cheapest.departureDate;
    const fire   = entry.price < TARGET ? ' 🔥' : '';
    const crown  = isBest ? ' 👑 *CHEAPEST*' : '';
    calLines.push(`• *${disp}*: *$${entry.price} USD*${fire}${crown}`);
  } else {
    calLines.push(`• *${disp}*: ❌ No data`);
  }
  cur = cur.plus({ days: 1 });
}
const calendarBlock = calLines.join('\n');

// Price trend
if (!sd.priceHistory) sd.priceHistory = [];
const lastPrice   = sd.lastPrice    || null;
const lastAlerted = sd.lastAlertedAt || 0;

let priceTrend = 'SAME';
if (lastPrice !== null) {
  if (Math.round(currentPrice * 100) < Math.round(lastPrice * 100)) priceTrend = 'DOWN';
  else if (Math.round(currentPrice * 100) > Math.round(lastPrice * 100)) priceTrend = 'UP';
}

const priceDiff  = lastPrice !== null ? Math.round((lastPrice - currentPrice) * 100) / 100 : 0;
const trendEmoji = priceTrend === 'DOWN' ? '📉' : priceTrend === 'UP' ? '📈' : '➡️';
const trendText  = priceTrend === 'DOWN'
  ? `dropped by $${Math.abs(priceDiff)} since last check`
  : priceTrend === 'UP'
    ? `rose by $${Math.abs(priceDiff)} since last check`
    : 'unchanged since last check';

sd.priceHistory.push({ price: currentPrice, at: checkedAt });
if (sd.priceHistory.length > 5) sd.priceHistory.shift();
const historyLine = sd.priceHistory.map(h => `$${h.price}`).join(' → ');

// Alert decision
const belowTarget = currentPrice < TARGET;
let shouldAlert   = false;
let alertReason   = '';

if (belowTarget) {
  if (lastPrice === null) {
    shouldAlert = true; alertReason = 'FIRST TIME BELOW TARGET';
  } else if (priceTrend === 'DOWN') {
    shouldAlert = true; alertReason = 'PRICE DROPPED BELOW TARGET';
  } else {
    const hrs = (Date.now() - lastAlerted) / (1000 * 60 * 60);
    if (hrs >= 2) { shouldAlert = true; alertReason = 'REMINDER — STILL BELOW TARGET'; }
  }
}

sd.lastPrice = currentPrice;
if (shouldAlert) sd.lastAlertedAt = Date.now();

return [{ json: {
  hasData:              true,
  belowTarget,
  shouldAlert,
  alertReason,
  currentPrice,
  lastPrice,
  priceDiff,
  priceTrend,
  trendEmoji,
  trendText,
  historyLine,
  calendarBlock,
  cheapestDate:         cheapest.departureDate,
  cheapestDateDisplay:  cheapest.displayDate,
  airline:              cheapest.airline,
  flightNumbers:        cheapest.flightNumbers,
  depTime:              cheapest.depTime,
  arrTime:              cheapest.arrTime,
  duration:             cheapest.duration,
  stopsLabel:           cheapest.stopsLabel,
  layovers:             cheapest.layovers,
  bookingLink:          cheapest.bookingLink,
  TARGET,
  checkedAt,
  periodLabel,
  datesChecked:         allDates.length,
  datesWithData:        available.length
}}];
